import { CommandeGerantService } from './CommandeGerant'
import { Order as DomainOrder, OrderItem as DomainOrderItem, OrderItemProps, OrderProps, OrderStatus } from '@/core/entities/Order'

export class CommandeScannerService {
  static async processScannedQRCode(qrText: string): Promise<DomainOrder | null> {
    console.log('[CommandeScannerService] Scanned QR payload:', qrText)
    try {
      // The QR payload was generated by GenerateOrderQRCodeUseCase, it's JSON string
      const decoded = JSON.parse(qrText)
      const orderId = decoded?.orderId || decoded?.id || decoded?.id_commande
      if (!orderId) throw new Error('Invalid QR code payload: missing orderId')

      // Fetch order details for this restaurant / gerant
      const order = await CommandeGerantService.getOrder(orderId)
      if (!order) throw new Error('Commande non trouvée')

      // Mark the order as delivered directly
      const updated = await CommandeGerantService.updateOrderStatus(orderId, 'livree')

      // Convert GerantOrder to Domain Order entity
      // Restaurant id is not returned by getOrder; we keep it empty or try to infer it later
      const restaurantId = ''
      const studentId = order.client?.id ? Number(order.client.id) : 0

      const itemsDomain: DomainOrderItem[] = (order.items || []).map((it: any, idx: number) => {
        const platId = it.plat_id ?? it.id ?? `${idx}`
        const platIdNum = Number(platId) || idx + 1
        const qty = Number(it.quantite ?? it.qty ?? 1) || 1
        const price = Number(it.prix ?? it.price ?? 0) || 0
        const props: OrderItemProps = {
          platId: platIdNum,
          platNom: it.nom || it.name || 'Plat inconnu',
          quantite: qty,
          prixUnitaire: price,
        }
        return new DomainOrderItem(props)
      })

      const orderIdNum = Number(order.id_commande) || Date.now()
      const createdAt = order.date_commande ? new Date(order.date_commande) : new Date()
      const totalPrice = Number(order.montant_total ?? itemsDomain.reduce((s, it) => s + it.calculateSubtotal(), 0))

      // Normalize status to domain OrderStatus
      const statutRaw = (order.statut || '').toLowerCase()
      let domainStatus: OrderStatus = OrderStatus.EN_ATTENTE
      if (statutRaw.includes('cours') || statutRaw.includes('prepar')) domainStatus = OrderStatus.EN_PREPARATION
      else if (statutRaw.includes('prete')) domainStatus = OrderStatus.PRETE
      else if (statutRaw.includes('livr') || statutRaw.includes('retire')) domainStatus = OrderStatus.RETIREE
      else if (statutRaw.includes('annul')) domainStatus = OrderStatus.ANNULEE

      const domainProps: OrderProps = {
        id: orderIdNum,
        studentId: studentId,
        restaurantId: restaurantId || '',
        items: itemsDomain,
        status: domainStatus,
        totalPrice,
        qrCode: qrText,
        createdAt,
        updatedAt: updated ? new Date() : undefined,
      }

      try {
        if (updated) domainProps.status = OrderStatus.RETIREE
        const domainOrder = new DomainOrder(domainProps)
        return domainOrder
      } catch (e) {
        console.error('[CommandeScannerService] error building Domain Order', e)
        return null
      }
    } catch (e) {
      console.error('[CommandeScannerService] Error processing QR scan', e)
      return null
    }
  }
}
